  'Okanzo encrypts your data on this device. Your data leaves it only when you export a backup. Price and exchange-rate lookups send only the ticker or currency code.':
      <String>[
        'Tus datos se guardan cifrados en este dispositivo y nunca salen de él, salvo al exportar una copia. Las consultas de precios solo envían el símbolo o el código de moneda.',
        'Seus dados ficam criptografados neste dispositivo e nunca saem dele, exceto ao exportar um backup. As consultas de preços enviam apenas o ticker ou o código da moeda.',
        'Vos données sont chiffrées sur cet appareil et ne le quittent jamais, sauf lors de l’exportation d’une sauvegarde. Les recherches de cours n’envoient que le symbole ou le code de devise.',
        'Deine Daten werden verschlüsselt auf diesem Gerät gespeichert und verlassen es nur beim Export eines Backups. Kursabfragen senden ausschließlich das Tickersymbol oder den Währungscode.',
        'データは暗号化されて端末内に保存され、バックアップのエクスポート時を除き外部に送信されません。価格照会で送信されるのはティッカーまたは通貨コードのみです。',
        '데이터는 이 기기에 암호화되어 저장되며 백업 내보내기 외에는 기기 밖으로 나가지 않습니다. 가격 조회 시 티커 또는 통화 코드만 전송됩니다.',
        '你的数据会加密存储在此设备上，除非导出备份，否则不会离开设备。价格查询仅发送股票代码或货币代码。',
        'I tuoi dati sono archiviati in modo criptato su questo dispositivo e non lo lasciano mai, tranne quando esporti un backup. Le richieste dei prezzi inviano solo il ticker o il codice valuta.',
        'आपका डेटा इस डिवाइस पर एन्क्रिप्टेड रहता है और बैकअप निर्यात करने के अलावा कभी बाहर नहीं जाता। कीमत देखने के लिए केवल टिकर या मुद्रा कोड भेजा जाता है।',
        'تُخزَّن بياناتك مشفرة على هذا الجهاز ولا تغادره مطلقًا إلا عند تصدير نسخة احتياطية. ترسل عمليات البحث عن الأسعار رمز التداول أو رمز العملة فقط.',
        'Data Anda disimpan terenkripsi di perangkat ini dan tidak pernah keluar, kecuali saat mengekspor cadangan. Pencarian harga hanya mengirim simbol ticker atau kode mata uang.',
        'Verileriniz bu cihazda şifrelenmiş olarak saklanır ve yedek dışa aktarma dışında cihazdan çıkmaz. Fiyat sorguları yalnızca hisse kodunu veya para birimi kodunu gönderir.',
        'Dane są szyfrowane na tym urządzeniu i nigdy go nie opuszczają, poza eksportem kopii zapasowej. Zapytania o ceny wysyłają tylko symbol giełdowy lub kod waluty.',
        'Je gegevens worden versleuteld op dit apparaat opgeslagen en verlaten het nooit, behalve bij het exporteren van een back-up. Prijsopvragingen versturen alleen het tickersymbool of de valutacode.',
        'Dữ liệu được mã hóa và lưu trên thiết bị này, không rời khỏi thiết bị trừ khi bạn xuất bản sao lưu. Tra cứu giá chỉ gửi mã chứng khoán hoặc mã tiền tệ.',
        'ข้อมูลของคุณจะถูกเข้ารหัสและเก็บไว้ในอุปกรณ์นี้ โดยจะไม่ออกจากอุปกรณ์ยกเว้นเมื่อส่งออกข้อมูลสำรอง การค้นหาราคาจะส่งเฉพาะรหัสหุ้นหรือรหัสสกุลเงิน',
        'Данные хранятся в зашифрованном виде на устройстве и не покидают его, кроме случаев экспорта резервной копии. Для запроса цены отправляется только тикер или код валюты.',
        'Dina data lagras krypterade på enheten och lämnar den aldrig, förutom när du exporterar en säkerhetskopia. Prisuppslag skickar bara aktiesymbolen eller valutakoden.',
        'Dine data gemmes krypteret på denne enhed og forlader den aldrig, undtagen når du eksporterer en sikkerhedskopi. Prisopslag sender kun aktiesymbolet eller valutakoden.',
        'Dataene dine lagres kryptert på denne enheten og forlater den aldri, bortsett fra når du eksporterer en sikkerhetskopi. Prisoppslag sender bare ticker- eller valutakoden.',
